import json
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
S=json.load(open('/app/output/spec.json'))
J=S['proprio']['joints']; P=np.array(S['proprio']['position_m']); AX=np.array(S['proprio']['axis'])
N=S['links']['names']; parents=dict(zip(N,S['links']['parent']))
# Every nonfixed link after pelvis corresponds to the joint at its parent attachment.
children=[n for n in N if n!='pelvis']
child_for_joint=dict(zip(J,children))
# This ordering differs for thumb: links still follow joint order; matches all 69.
parent_joint={c:j for j,c in child_for_joint.items()}

def screw(j,q):
    k=J.index(j); R=Rotation.from_rotvec(AX[k]*q).as_matrix(); T=np.eye(4); T[:3,:3]=R; T[:3,3]=P[k]-R@P[k]; return T

def tf(link,q):
    chain=[]
    while link!='pelvis':
        chain.append(parent_joint[link]); link=parents[link]
    T=np.eye(4)
    for j in reversed(chain): T=T@screw(j,q.get(j,0))
    return T

def pt(link,p,q):
    T=tf(link,q); return T[:3,:3]@np.array(p)+T[:3,3]

def hand(q,side='left',point=None):
    if point is None: point=[.42,.214 if side=='left' else -.214,.087]
    return pt('lh_palm' if side=='left' else 'rh_palm',point,q)

C=S['cameras']['room_camera']['pose']; cp=np.array(C['position_m']); fw=np.array(C['forward']); up=np.array(C['up']); rt=np.array(C['right']); f=128/np.tan(np.pi/8)

def ray(u,v):
    return fw+rt*(u-128)/f-up*(v-128)/f

def unproject(u,v,z):
    d=ray(u,v); return cp+d*((z-cp[2])/d[2])

def project(p):
    d=np.array(p)-cp; return np.array([128+f*(d@rt)/(d@fw),128-f*(d@up)/(d@fw)])

if __name__=='__main__':
    a=json.load(open('/app/output/initial/meta.json')); vals=a['proprio']['now']; q=dict(zip(J,vals))
    # infer height from the two soles and initial gravity orientation
    g=np.array(vals[-3:]); rot=Rotation.align_vectors([[0,0,-1]],[g])[0].as_matrix()
    foot=[]
    for side in ['left','right']:
        b=S['links']['feet'][side+'_ankle_link'];
        for x in [b[0][0],b[1][0]]:
            for y in [b[0][1],b[1][1]]:
                for z in [b[0][2],b[1][2]]:foot.append(rot@pt(side+'_ankle_link',[x,y,z],q))
    height=-np.min(np.array(foot)[:,2]); print('height',height, 'rot',rot)
    np.savez('/app/output/base_initial.npz',R=rot,height=height)
    for s in ['left','right']:
        p=rot@hand(q,s)+[0,0,height];print(s,p,project(p))
    for z in [.75,.8,.85,.9]:
        print('z',z)
        for n,uv in [('black',(82,108)),('white',(140,161)),('bar_white',(126,101)),('bar_black',(165,134))]: print(n,unproject(*uv,z))
PY
