from geometry import *
def base_from_q(meta):
 vals=meta['proprio']['now'];q=dict(zip(J,vals)); g=np.array(vals[-3:]);rot=Rotation.align_vectors([[0,0,-1]],[g])[0].as_matrix()
 foot=[]
 for side in ['left','right']:
  b=S['links']['feet'][side+'_ankle_link'];
  for x in [b[0][0],b[1][0]]:
   for y in [b[0][1],b[1][1]]:
    foot.append(rot@pt(side+'_ankle_link',[x,y,b[0][2]],q))
 height=-np.min(np.array(foot)[:,2])
 # Assuming feet have not slid, derive horizontal pelvis displacement from ankle centres.
 init=json.load(open('/app/output/initial/meta.json'));qi=dict(zip(J,init['proprio']['now']));B=np.load('/app/output/base_initial.npz')
 offs=[]
 for s in ['left','right']:
  p=P[J.index(s+'_ankle')];offs.append((B['R']@pt(s+'_ankle_link',p,qi)-rot@pt(s+'_ankle_link',p,q))[:2])
 off=np.mean(offs,axis=0);base=np.array([*off,height])
 return rot,base,q
if __name__=='__main__':
 m=json.load(open('/app/output/current.json'));R,b,q=base_from_q(m);print('base',b,'rot',R)
 for s in ['left','right']:
  w=R@hand(q,s)+b;print(s,w,project(w))
